def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[()+*/,:<>=-]")
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "u-": 3,
    }
    values = {}
    active = set()

    def parse(formula):
        tokens = token_pattern.findall(formula)
        nodes = []
        operators = []
        expecting_operand = True
        i = 0

        def apply_operator():
            op = operators.pop()
            if op == "u-":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(["(", token, 0])
                i += 2  # Skip the function name and opening parenthesis.
                expecting_operand = True
                continue

            if token == "(":
                operators.append(["(", None, 0])
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    apply_operator()
                operators[-1][2] += 1
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    apply_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = nodes[-count:]
                    del nodes[-count:]
                    if function == "IF":
                        nodes.append(("if", args[0], args[1], args[2]))
                    else:
                        nodes.append(("function", function, args))
                expecting_operand = False
            elif token in precedence:
                op = "u-" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "u-"
                        )
                    )
                ):
                    apply_operator()
                operators.append(op)
                expecting_operand = True
            elif token[0].isdigit():
                nodes.append(("number", int(token)))
                expecting_operand = False
            else:
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    other = tokens[i + 2]
                    col1, row1 = ord(token[0]), int(token[1:])
                    col2, row2 = ord(other[0]), int(other[1:])
                    nodes.append((
                        "range",
                        min(row1, row2),
                        max(row1, row2),
                        min(col1, col2),
                        max(col1, col2),
                    ))
                    i += 2
                else:
                    nodes.append(("reference", token))
                expecting_operand = False
            i += 1

        while operators:
            apply_operator()
        return nodes[0]

    def function_items(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue
            _, first_row, last_row, first_col, last_col = arg
            for row in range(first_row, last_row + 1):
                for col in range(first_col, last_col + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def evaluate(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name in active:
                    results.append("#CYCLE!")
                elif name not in cells:
                    results.append(0)
                else:
                    content = cells[name]
                    if not content.startswith("="):
                        value = int(content)
                        values[name] = value
                        results.append(value)
                    else:
                        active.add(name)
                        tasks.append(("finish_cell", name))
                        tasks.append(("evaluate", parse(content[1:])))

            elif kind == "finish_cell":
                name = task[1]
                active.remove(name)
                values[name] = results[-1]

            elif kind == "evaluate":
                node = task[1]
                node_kind = node[0]
                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("neg",))
                    tasks.append(("evaluate", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("evaluate", node[2]))
                elif node_kind == "if":
                    tasks.append(("if", node[2], node[3]))
                    tasks.append(("evaluate", node[1]))
                else:
                    tasks.append((
                        "function_next",
                        node[1],
                        iter(function_items(node[2])),
                        None,
                    ))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("evaluate", task[1] if condition else task[2]))

            elif kind == "function_next":
                function, items, accumulator = task[1:]
                item = next(items, None)
                if item is None:
                    results.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("function_collect", function, items, accumulator))
                    tasks.append(("evaluate", item))

            else:  # function_collect
                function, items, accumulator = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("function_next", function, items, accumulator))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
